const SPD=[['Na okraji lesa stála stará hájovna.',['hájovna'],['stála']],['Včera večer nám utekl sousedovic pes.',['pes'],['utekl']],['Z komína stoupal hustý šedý kouř.',['kouř'],['stoupal']],['Moje sestra bude v létě pracovat v knihovně.',['sestra'],['bude pracovat']],['Po dlouhém čekání se konečně otevřely dveře.',['dveře'],['otevřely se','se otevřely']],['Malému Tomášovi se nový kamarád hned zalíbil.',['kamarád'],['zalíbil se','se zalíbil']],['Výlet do Brna byl pro celou třídu zážitkem.',['výlet'],['byl zážitkem']],['Na stole ležely rozházené sešity a učebnice.',['sešity a učebnice','sešity, učebnice'],['ležely']]];
