// 6 – přiřazování 3/5
const MATCH3=[
 ['Přiřaďte k jednotlivým souvětím (6.1–6.3) druh vedlejší věty (A–E).',['Vím, že se zítra vrátíš.','Když zazvonil zvonek, děti vyběhly ven.','Kniha, kterou jsi mi půjčil, je napínavá.'],['vedlejší věta přívlastková','vedlejší věta předmětná','vedlejší věta příslovečná časová','vedlejší věta příslovečná příčinná','vedlejší věta podmětná'],[1,2,0],'Vím (co?) – předmětná; kdy vyběhly? – časová; kniha (jaká?) – přívlastková.'],
 ['Přiřaďte ke každé větě (6.1–6.3) slovní druh podtrženého slova (A–E).',['Šli jsme <u>kolem</u> řeky.','Auto projelo <u>kolem</u>.','<u>Ach</u>, to je krása!'],['předložka','příslovce','citoslovce','částice','spojka'],[0,1,2],'Kolem řeky – předložka s 2. pádem; projelo kolem – příslovce (samostatně, bez podstatného jména); ach – citoslovce.'],
 ['Přiřaďte ke každé větě (6.1–6.3) způsob slovesa, který je v ní užit (A–E).',['Kdybych to věděl, přišel bych.','Zavři okno!','Zítra pojedeme k moři.'],['oznamovací způsob, čas budoucí','oznamovací způsob, čas minulý','rozkazovací způsob','podmiňovací způsob přítomný','podmiňovací způsob minulý'],[3,2,0],'Přišel bych = podmiňovací přítomný; zavři = rozkazovací; pojedeme = oznamovací budoucí.'],
 ['Přiřaďte k jednotlivým dvojicím slov (6.1–6.3) vztah, který mezi nimi platí (A–E).',['velký – malý','kůň – oř','strom – dub'],['antonyma','synonyma','slovo nadřazené a podřazené','homonyma','slova příbuzná'],[0,1,2],'Velký × malý = antonyma; oř je básnické synonymum ke kůň; dub je druh stromu (strom je nadřazený).']];
