const FORM=[['Mluvili jsme o (oba) ***** výletech a o (svůj) ***** plánech.',[['obou'],['svých']]],['Na schodech jsme potkali paní učitelku se (dvě) ***** taškami.',[['dvěma']]],['Ten obraz visí nad (krb) ***** v našem (pokoj) ***** už deset let.',[['krbem'],['pokoji']]],['Před (dům) ***** zaparkovalo auto s (německý) ***** poznávací značkou.',[['domem'],['německou']]],['Pomoz mi s (ten) ***** (kufr) *****, prosím.',[['tím'],['kufrem']]],['Zeptej se (ty) ***** chlapců, jestli by nám se (stěhování) ***** pomohli.',[['těch'],['stěhováním']]],['Sešli jsme se s (naši) ***** (sousedé) ***** na zahradě.',[['našimi'],['sousedy']]]].filter(x=>x[1].length===2);
