// 14 – interpunkce (svazek ANO/NE)
const INT=[[['Myslím, že tě pochopí.',true],['Přišel domů a hned usnul.',true],['Nevím jestli přijde.',false],['Petr, který bydlí vedle nás má nové kolo.',false],'Chybí čárka: „Nevím, jestli přijde.“; vložená vedlejší věta musí být oddělena z obou stran: „…vedle nás, má…“.'],
 [['Až se vrátíš, zavolej mi.',true],['Bylo chladno ale nepršelo.',false],['Koupili jsme jablka, hrušky a švestky.',true],['Byl unavený, a proto šel brzy spát.',true],'Před odporovací spojkou „ale“ se píše čárka. Před „a proto“ (důsledek) čárka patří.'],
 [['Nejen že zvítězil, ale překonal i rekord.',true],['Řekla, abychom počkali, a odešla.',true],['Čím víc se učíš tím víc umíš.',false],['Pes, kterého jsme našli, se jmenuje Ťapka.',true],'„Čím víc se učíš, tím víc umíš.“ – dvě věty je nutné oddělit čárkou. Ve 2. souvětí čárka před „a“ uzavírá vloženou vedlejší větu.'],
 [['Jestli chceš můžeš jet s námi.',false],['Ať se stane cokoli, budu stát při tobě.',true],['Ozval se hrom a začalo pršet.',true],['Zavolala, že nepřijde, ale nevysvětlila proč.',true],'„Jestli chceš, můžeš jet s námi.“ Před „a“ ve slučovacím poměru se čárka nepíše.'],
 [['Zeptal se mě, kdy začíná film.',true],['Ačkoli bylo pozdě nikdo nechtěl odejít.',false],['Babička, dědeček a teta přijeli včas.',true],['Když jsme dorazili na nádraží vlak už odjížděl.',false],'Vedlejší věta na začátku souvětí se odděluje čárkou: „Ačkoli bylo pozdě, nikdo…“, „Když jsme dorazili na nádraží, vlak…“.']];
PQ.bank('cj14',INT);
slot('cj14','Interpunkce v souvětí (ANO/NE)',one('Interpunkce',()=>{const x=PQ.drawItems(PQ.BANKS.cj14).d;return S.yn('Rozhodněte o každém z následujících souvětí, zda je v něm správně zapsána interpunkce (A), či nikoli (N).',PQ.shuffle(x.slice(0,4)),2,SC4,x[4]);}),{});
// 15 – řazení 6 částí
const ORD=[
 ['Když jsem v sobotu ráno otevřel dveře, ležela na rohožce malá krabice bez odesílatele.','Opatrně jsem ji odnesl do kuchyně a chvíli jen poslouchal, jestli z ní něco neuslyším.','Pak jsem sebral odvahu a nůžkami přestřihl provázek.','Uvnitř, zabalený do starých novin, ležel mosazný zámek bez klíče.','Teprve na dně krabice jsem objevil lístek: „Klíč najdeš tam, kde jsi byl naposledy šťastný.“','Celý ten den jsem pak strávil obcházením míst, na která jsem už dávno zapomněl.'],
 ['Kdo chce zasadit ovocný strom, měl by nejprve vybrat vhodné místo.','Takové místo má být slunné a chráněné před silným větrem.','Na něm pak vykopeme jámu, která je asi dvakrát širší než kořenový bal.','Do jámy zatlučeme kůl, ke kterému později stromek přivážeme.','Teprve potom stromek vložíme dovnitř, jámu zasypeme zeminou a mírně ji ušlapeme.','Nakonec stromek vydatně zalijeme, i když zrovna prší.'],
 ['První jízdní kola neměla pedály.','Jezdec na nich seděl a odrážel se nohama od země, podobně jako dnešní děti na odrážedlech.','Pedály se objevily až o několik desetiletí později, a to přímo na předním kole.','Aby kolo s takovým pohonem jelo rychle, muselo být přední kolo obrovské.','Z vysokých strojů se ale často padalo, a proto konstruktéři hledali bezpečnější řešení.','Tím se stal řetěz, který přenáší sílu z pedálů na zadní kolo a používá se dodnes.'],
 ['Marta si všimla, že někdo zapomněl v autobuse na sedadle deštník.','Rozhlédla se, ale nikdo z cestujících se k němu nehlásil.','Na příští zastávce proto deštník odnesla řidiči.','Ten jen pokrčil rameny a řekl, že ho odevzdá do ztrát a nálezů.','Když Marta vystoupila, začalo hustě pršet.','Promoklá na kost se musela smát: deštník by se jí teď opravdu hodil.']];
PQ.bank('cj15',ORD);
slot('cj15','Řazení částí textu',one('Řazení textu',()=>{const x=PQ.drawItems(PQ.BANKS.cj15).d;const s=S.ord('Seřaďte jednotlivé části textu (A–F) tak, aby na sebe navazovaly. Klepej na části v pořadí, v jakém mají následovat.',x,3,{6:3,4:2,3:1},'Vodítka: zájmena a příslovce odkazující dozadu (ji, na něm, ten, takové), časová slova (pak, teprve, nakonec) a logika děje.');s.view=PQ.shuffle(x.map((_,i)=>i));return s;}),{});
// 16 – gramatická správnost
const GR=[['Na výstavě jsme viděli obrazy ***** malířů.',['obou českých','oboum českým','obou českým','oběma českých'],'Obrazy (čeho?) obou českých malířů – 2. pád.'],['Ředitel poděkoval *****, kteří pomohli s přípravou.',['všem rodičům','všechem rodičům','všem rodičů','všemi rodičům'],'Poděkoval (komu?) všem rodičům – 3. pád.'],['Seděli jsme u stolu s *****.',['našimi přáteli','našima přátelama','našimi přátelmi','našich přátelích'],'S (kým?) našimi přáteli – spisovný 7. pád mn. č.'],['Kdyby ***** včas, stihli bychom vlak.',['jsme vyrazili','bychom vyrazili','bysme vyrazili','by jsme vyrazili'],'Kdyby + příčestí: „kdybychom vyrazili“ – po „kdyby“ už se „bychom“ neopakuje; tvar „kdyby jsme“ je chybný, správně „kdybychom vyrazili“.'],['Bez ***** bychom to nezvládli.',['tvé pomoci','tvý pomoci','tvou pomoci','tvé pomocí'],'Bez (čeho?) tvé pomoci – 2. pád.'],['Dej to ***** dívce v modrém.',['té','tý','tou','ta'],'Dej to (komu?) té dívce – 3. pád.']].filter(x=>!/Kdyby/.test(x[0]));
PQ.bank('cj16',GR);
slot('cj16','Gramatická správnost',one('Mluvnice',()=>{const x=PQ.drawItems(PQ.BANKS.cj16).d;return M(`Která z následujících možností patří na vynechané místo, aby věta byla spisovná a gramaticky správná?<br><i>${x[0]}</i>`,x[1],x[2]);}),{});
// 17 – slohový útvar / výpisky
const SLOH=[['<p>Hledám spolehlivou paní na hlídání osmiletého syna, dvakrát týdně od 15 do 18 hodin, Praha 6. Nabídky na tel. 777 123 456.</p>','Který slohový útvar představuje výchozí text?',['inzerát','zpráva','úvaha','popis pracovního postupu'],'Krátké sdělení s nabídkou/poptávkou a kontaktem = inzerát.'],
 ['<p>Co je to vlastně odvaha? Je odvážný ten, kdo se ničeho nebojí, nebo spíš ten, kdo se bojí, a přesto jedná? Myslím, že skutečná odvaha nezačíná tam, kde strach chybí, ale tam, kde ho dokážeme překonat.</p>','Který slohový útvar představuje výchozí text?',['úvaha','líčení','výklad','životopis'],'Autor klade otázky a hledá na ně vlastní odpověď – úvaha.'],
 ['<p>Ve čtvrtek odpoledne došlo v Lipové ulici k prasknutí vodovodního potrubí. Opravu zajistili pracovníci vodáren během čtyř hodin, dodávka vody byla obnovena v 19 hodin.</p>','Který slohový útvar představuje výchozí text?',['zpráva','vypravování','fejeton','charakteristika'],'Věcné sdělení o události (kdy, kde, co) – zpráva.'],
 ['<p><b>Výpisky k referátu:</b> Karel Čapek (1890–1938) – spisovatel, novinář; hra R.U.R. (1920) – slovo <i>robot</i>, vymyslel ho bratr Josef; dále romány, pohádky, fejetony.</p>','Které z následujících tvrzení o výchozím textu je pravdivé?',['Jde o výpisky – informace jsou zapsány heslovitě, často bez úplných vět.','Jde o vypravování v ich-formě.','Jde o dopis s oslovením a podpisem.','Jde o líčení s mnoha básnickými prostředky.'],'Heslovitý zápis se závorkami a pomlčkami = výpisky.'],
 ['<p>Vážený pane řediteli,<br>obracím se na Vás s žádostí o uvolnění mé dcery z vyučování dne 12. května z důvodu rodinné oslavy.<br>S pozdravem Jana Nováková</p>','Který slohový útvar představuje výchozí text?',['žádost','osobní dopis','inzerát','pozvánka'],'Oficiální oslovení, žádost o něco a podpis – úřední dopis, žádost.']];
PQ.bank('cj17',SLOH);
slot('cj17','Slohový útvar a výpisky',()=>{const x=PQ.drawItems(PQ.BANKS.cj17).d;return [PQ.T('Sloh',[M(x[1],x[2],x[3])],{src:{h:x[0],lab:'Výchozí text'}})];});
// 18 – najdi a oprav 4 chyby
const ERR=[
 'Minulý týden jsme s celou třídou navštívili hvězdárnu. Průvodce nám ukázal [obrovsky|obrovský|Jaký dalekohled? Tvrdé přídavné jméno – koncovka -ý.] dalekohled a dovolil [mě|mi/mně|Komu dovolil? Ve 3. pádě je správně mi nebo mně; tvar mě je 2. a 4. pád.], abych se podíval jako první. Nejvíc nás [zaujali|zaujaly|Podmět prstence je rodu mužského neživotného → zaujaly.] prstence Saturnu. Domů jsme pak [zjeli|sjeli|Pohyb shora dolů – předpona s-: sjet.] lanovkou.',
 'Naše babička bydlí v malé vesnici u Labe. Každý rok k ní jezdíme na [prázniny|prázdniny|Prázdniny souvisí se slovem prázdný – píšeme -zdn-.]. Za domem má zahradu, kde rostou jabloně a [vyšně|višně|Višně nejsou vyjmenované ani příbuzné slovo – píšeme i.]. Vstáváme [s rána|zrána|Příslovce zrána se píše dohromady a s předponou z-.] a večer posloucháme, jak dědeček vypráví o [svích|svých|Zájmeno svůj má v 6. pádě mn. č. tvar svých.] dobrodružstvích.',
 'Kluci z vedlejší třídy [postavily|postavili|Podmět kluci je rodu mužského životného → postavili.] na hřišti sněhuláka. Oči měl z [uhlý|uhlí|Uhlí se píše s měkkým í (podle stavení).] a místo nosu mrkev. Když se ale oteplilo, začal se [pomaly|pomalu|Příslovce pomalu končí na -u.] rozpouštět. Nakonec mu vítr [zhodil|shodil|Pohyb shora dolů – předpona s-: shodit.] z hlavy hrnec.',
 'Na výstavě jsme viděli psy všech velikostí. Nejvíc se nám líbila fenka, kterou majitel [cvyčí|cvičí|Po c píšeme vždy i.] už od štěněte. Na povel si sedla a podala [mě|mi/mně|Komu podala? Ve 3. pádě mi nebo mně; mě je 2. a 4. pád.] tlapku. Porotci jí nakonec [udělily|udělili|Podmět porotci je rodu mužského životného → udělili.] první cenu a všichni diváci [tleskaly|tleskali|Podmět diváci je rodu mužského životného → tleskali.].',
 'Turisté se ráno [vydaly|vydali|Podmět turisté je rodu mužského životného → vydali.] na Pražský hrad. Průvodkyně jim ukázala katedrálu a vyprávěla o Karlu IV. Ze zahrad byl krásný výhled na [vltavu|Vltavu|Název řeky je vlastní jméno – píšeme velké V.]. Cestou zpět si koupili [suvenýri|suvenýry|Suvenýr – 4. pád mn. č. rodu mužského neživotného má koncovku -y.] a v kavárně si dali [zmrzlynu|zmrzlinu|Zmrzlina – po l zde píšeme i, nejde o vyjmenované slovo.].'];
const errParse=w=>{const E=[];const plain=w.replace(/\[([^\]|]*)\|([^\]|]*)\|([^\]]*)\]/g,(m,a,b,r)=>{E.push({w:a,r:b.split('/'),rule:r});return a;});return {plain,E};};
PQ.bank('cj18',ERR);
PQ.CJ.errParse=errParse;
slot('cj18','Najdi a oprav 4 pravopisné chyby',()=>{const {plain,E}=errParse(PQ.drawItems(PQ.BANKS.cj18).d);
  return [PQ.T('Pravopisné chyby',[S.fields('Výchozí text obsahuje <b>čtyři</b> slova s pravopisnou chybou. Najděte je a napište je správně (pořadí nehraje roli).',E.map((x,i)=>({l:`${i+1}.`,a:x.r,show:x.r[0]})),4,E.map(x=>`<b>${x.w}</b> → <b>${x.r.join(' / ')}</b>: ${x.rule}`).join('<br>'),{minus:1,any:1})],{src:{h:`<p>${plain}</p>`,lab:'Výchozí text'}})];});
// 24 – přejatá slova
const LOAN=[['fyzika, gymnázium, cyklistika','fizika, gymnázium, cyklistika','fyzika, gimnázium, cyklistika','fyzika, gymnázium, cyklystika'],['diskuse, typický, pyžamo','dyskuse, typický, pyžamo','diskuse, tipický, pyžamo','diskuse, typický, pižamo'],['olympiáda, synonymum, hypotéza','olimpiáda, synonymum, hypotéza','olympiáda, sinonymum, hypotéza','olympiáda, synonymum, hipotéza'],['systém, symbol, rytmus','sistém, symbol, rytmus','systém, simbol, rytmus','systém, symbol, ritmus'],['analýza, encyklopedie, pyramida','analíza, encyklopedie, pyramida','analýza, encyklopédie, pyramida','analýza, encyklopedie, piramida']];
PQ.bank('cj24',LOAN);
slot('cj24','Pravopis přejatých slov',one('Přejatá slova',()=>{const x=PQ.drawItems(PQ.BANKS.cj24).d;return M('Ve které z následujících možností jsou všechna slova zapsána pravopisně správně?',x,`Správně: ${x[0]}. U přejatých slov se pravopis i/y učíme zpaměti (y často odpovídá řeckému ypsilon).`);}),{});
// 25 – nespisovné tvary sloves
const NS=[[['Zítra si koupím nové boty.','Babička nám upekla bábovku.','Já to snad nevydržim.','Pomoz mi s tou taškou.','Rodiče odjeli na chatu.','Ten film jsme viděli dvakrát.','Sousedi se o všechno starajou.','Kdybys chtěl, můžeš jít s námi.','Zavři prosím za sebou dveře.','Vem si deštník, venku prší.','Dědeček mi vyprávěl o svém mládí.','Psi štěkali celou noc.'],[3,7,10],'nevydržim → nevydržím, starajou → starají, vem → vezmi.'],
 [['Přijdu za tebou hned po škole.','Bysme to měli stihnout do večera.','Děti si hrají na zahradě.','Vezmi si ještě jeden koláč.','Myslím, že má pravdu.','Kluci řikali, že přijdou.','Utíkej, ať nezmeškáš autobus.','Sestra umí krásně zpívat.','Včera jsme byli v kině.','Nevím, kam jsem dal klíče.','Oni to stejně nepochopěj.','Učitel nám vrátil písemky.'],[2,6,11],'bysme → bychom, řikali → říkali, nepochopěj → nepochopí.'],
 [['Ráno jsem zaspal a nestihl autobus.','Pomůžeš mi s úkolem?','Ptáci odlétají na jih.','Jestli chceš, pučim ti tu knížku.','Nechte to na mně.','Máma peče perník.','Lyžaři čekali na vlek.','Já to přece vim.','Nezapomeň si pláštěnku.','Pes se schoval pod stůl.','Kdy se vrátíte z hor?','Děti se hrozně těšej na prázdniny.'],[4,8,12],'pučim → půjčím, vim → vím, těšej → těší.']];
PQ.bank('cj25',NS);
slot('cj25','Nespisovné tvary sloves',one('Spisovnost',()=>{const x=PQ.drawItems(PQ.BANKS.cj25).d;return S.nums('Ve kterých třech větách je užit <b>nespisovný tvar slovesa</b>? Napište čísla těchto vět.',x[0],x[1],3,`Nespisovné jsou věty ${x[1].join(', ')}: ${x[2]}`);}),{});
// 30 – přiřazování 4/6
const MATCH4=[
 ['Přiřaďte k jednotlivým ukázkám (30.1–30.4) básnický prostředek, který je v nich užit (A–F).',['<i>Vítr si v korunách zpívá svou píseň.</i>','<i>Jsi jako slunce po dešti.</i>','<i>Ptám se tě, kdo jsi. / Ptám se tě, kam jdeš.</i>','<i>Moře lidí se valilo náměstím.</i>'],['přirovnání','metafora','personifikace','anafora (opakování slov na začátku veršů)','epiteton','zvukomalba'],[2,0,3,1],'Vítr zpívá – zosobnění (personifikace); „jako slunce“ – přirovnání; „Ptám se tě“ na začátku veršů – anafora; „moře lidí“ – metafora (přenesení na základě podobnosti).'],
 ['Přiřaďte k jednotlivým souvětím (30.1–30.4) druh vedlejší věty (A–F).',['Kdo se bojí, nesmí do lesa.','Řekl, že přijde později.','Dům, ve kterém bydlíme, je starý.','Protože pršelo, zůstali jsme doma.'],['podmětná','předmětná','přívlastková','příslovečná časová','příslovečná příčinná','příslovečná účelová'],[0,1,2,4],'Kdo nesmí? – podmětná; řekl (co?) – předmětná; dům (jaký?) – přívlastková; proč jsme zůstali? – příčinná.'],
 ['Přiřaďte k jednotlivým popisům (30.1–30.4) literární útvar (A–F).',['Krátký epický útvar, v němž zvířata jednají jako lidé a z příběhu plyne ponaučení.','Lidové vyprávění spojené s určitým místem nebo historickou postavou, často s prvky nadpřirozena.','Lyrickoepický útvar s ponurým dějem, který obvykle končí tragicky.','Krátká, často veršovaná báseň s vtipnou, nečekanou pointou.'],['bajka','pověst','balada','epigram','sonet','román'],[0,1,2,3],'Bajka – zvířata a ponaučení; pověst – místo/historie; balada – tragický konec; epigram – vtipná pointa.'],
 ['Přiřaďte ke každé větě (30.1–30.4) slovní druh podtrženého slova (A–F).',['<u>Dvakrát</u> jsem zazvonil.','Venku je <u>krásně</u>.','<u>Kéž</u> by už bylo léto!','Čekali jsme <u>před</u> divadlem.'],['podstatné jméno','číslovka','příslovce','částice','předložka','spojka'],[1,2,3,4],'Dvakrát – číslovka (násobná); krásně – příslovce; kéž – částice (vyjadřuje přání); před – předložka.']];
PQ.bank('cj30',MATCH4);
slot('cj30','Přiřazování (4 z 6)',one('Přiřazování',()=>{const x=PQ.drawItems(PQ.BANKS.cj30).d;const pm=PQ.shuffle(x[2].map((_,i)=>i));return S.match(x[0],x[1],pm.map(i=>x[2][i]),x[3].map(k=>pm.indexOf(k)),4,x[4]);}),{});

